"""Parse a string value to bool"""
def parse_bool(data: Any) -> object {
    if (data.lower() in ('yes', 'true')) {
        return True;
    } elif (data.lower() in ('no', 'false')) {
        return False;
    } else {
        err = f'"{data}" could not be interpreted as a boolean';
        raise TypeError(err);
    }
}

